function adminLog(action,target,reason){state.adminLog.unshift({id:uid(),day:state.day,actor:'lifexp_admin',action,target,reason});save()}
function adminHeading(title,subtitle){return `<div class="row between wrap">${heading(title,subtitle)}<a href="#admin-security" class="btn compact">管理账号</a></div>`}
function adminOverview(){const users=state.users.filter(u=>u.role==='user');return adminHeading('管理概览','独立管理工作区，统计与个人记录分开。')+`<div class="three-col">${[[users.length,'用户账号','不含管理账号'],[users.filter(u=>u.status==='active').length,'正常用户','可以使用系统'],[users.filter(u=>u.status==='disabled').length,'停用用户','保留数据'],[users.filter(u=>u.created===state.day).length,'今日新增',state.day],[users.filter(u=>u.lastLogin>=shift(state.day,-6)).length,'近 7 日登录','按账号去重'],[state.users.filter(u=>u.role==='admin').length,'管理账号','单独统计']].map(([v,n,d])=>`<section class="card stat"><strong>${v}</strong><h3>${n}</h3><span>${d}</span></section>`).join('')}</div><div class="two-col mt"><section class="card"><h2>常用管理操作</h2>${[['admin-users','用户账号'],['admin-notices','公告管理'],['admin-feedback','用户反馈'],['admin-site','站点设置'],['admin-audit','操作记录']].map(([r,n])=>`<a class="list-row" href="#${r}">${n}${icon('arrow')}</a>`).join('')}</section><section class="card"><h2>最近管理操作</h2>${auditRows(state.adminLog.slice(0,4))}<p class="note mt">不提供查看用户日记、问卷、密码或 API Key 的入口。这里的人数和账号均为虚构样例。</p></section></div>`}
function adminUsers(){const f=state.userFilter||{query:'',status:'all',role:'all'},rows=state.users.filter(u=>(!f.query||u.username.toLowerCase().includes(f.query.toLowerCase()))&&(f.status==='all'||u.status===f.status)&&(f.role==='all'||u.role===f.role));return adminHeading('用户账号','搜索与管理账号状态，个人内容仍属于用户。')+`<section class="card"><div class="form-grid"><label class="field">查找账号<input id="user-query" value="${esc(f.query)}" placeholder="输入用户名"></label><label class="field">状态<select id="user-status">${[['all','所有状态'],['active','正常'],['disabled','已停用']].map(([v,n])=>`<option value="${v}" ${f.status===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">身份<select id="user-role">${[['all','所有身份'],['user','普通用户'],['admin','管理员']].map(([v,n])=>`<option value="${v}" ${f.role===v?'selected':''}>${n}</option>`).join('')}</select></label></div><button class="btn" data-full="search-users">搜索</button><p class="small muted mt">${rows.length} 个匹配账号</p><div class="table-wrap"><table><thead><tr><th>账号</th><th>身份 / 验证</th><th>状态</th><th>注册日期</th><th>最近登录</th><th>操作</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${esc(u.username)}</td><td>${u.role==='admin'?'管理员':'普通用户'}<br>${u.verified?'邮箱已验证':'邮箱待验证'}</td><td>${u.status==='active'?'正常':'已停用'}</td><td>${u.created}</td><td>${u.lastLogin||'尚未登录'}</td><td>${u.role==='admin'?'<span class="small muted">管理账号不在此停用</span>':`<button class="btn compact" data-full="manage-user" data-id="${u.id}">${u.status==='active'?'停用':'恢复'}</button>`}</td></tr>`).join('')||'<tr><td colspan="6">没有匹配的账号。</td></tr>'}</tbody></table></div></section>`}
function adminNotices(){const n=state.noticeDraft||state.noticeData;return adminHeading('公告管理','编辑、预览、发布和撤下，在同一份 Demo 中同步。')+`<div class="two-col"><section class="card"><label class="field">标题<input id="notice-title" maxlength="100" value="${esc(n.title)}"></label><label class="field">内容<textarea id="notice-body" maxlength="2000">${esc(n.body)}</textarea></label><div class="row wrap"><button class="btn" data-full="preview-notice">预览</button><button class="btn primary" data-full="publish-notice">发布到示例首页</button><button class="btn danger" data-full="withdraw-notice" ${!state.noticeData.published?'disabled':''}>撤下</button></div></section><section class="card"><h2>当前发布状态</h2><span class="tag ${state.noticeData.published?'green':''}">${state.noticeData.published?'已发布':'未发布'} · v${state.noticeData.version}</span><p class="quote">${esc(state.noticeData.title)}</p><p class="small muted">发布后普通账号首页和“站点公告”可以查看；撤下后同步消失。</p></section></div>`}
function adminSite(){return adminHeading('站点设置','只调整站点级选项，个人模型和个人记录各自独立。')+`<section class="card"><label class="field">站点名称<input id="site-name" maxlength="60" value="${esc(state.site.name)}"></label><label class="field">站点说明<textarea id="site-intro" maxlength="500">${esc(state.site.intro)}</textarea></label><label class="check-option"><input type="checkbox" id="site-registration" ${state.site.registration?'checked':''}>允许普通用户直接注册</label><div class="note mt"><strong>站点共享 AI：关闭</strong><p>本轮采用用户自配模型，通用 AI 助手与站点付费共享服务暂缓。不会因为在 Demo 操作就产生真实调用或费用。</p></div><button class="btn primary mt" data-full="save-site">保存站点设置</button></section>`}
function adminFeedback(){return adminHeading('用户反馈','投稿者与授权管理员之间的站内沟通。')+`<section class="card">${state.feedback.map(f=>`<article class="feedback-item"><div class="row between wrap"><h3>${esc(f.title)}</h3><span class="tag ${f.reply?'green':''}">${f.reply?'已回复':'待处理'}</span></div><p class="small muted">来自 ${esc(f.username||state.account.username)} · ${f.day}</p><p class="feedback-message">${esc(f.text)}</p>${f.reply?`<p class="feedback-message reply">${esc(f.reply)}</p>`:''}<label class="field">站内回复<textarea id="reply-${f.id}" placeholder="回复只对提交者可见。">${esc(f.reply||'')}</textarea></label><button class="btn" data-full="reply-feedback" data-id="${f.id}">保存并回复</button></article>`).join('')||'<p class="empty">暂无反馈；可在普通体验“我的 → 意见与问题”提交。</p>'}</section>`}
function auditRows(rows){return rows.map(a=>`<div class="list-row"><div><h3>${esc(a.action)} · ${esc(a.target)}</h3><small>${a.day} · ${esc(a.actor)} · ${esc(a.reason)}</small></div></div>`).join('')||'<p class="empty">还没有管理操作。</p>'}
function adminAudit(){return adminHeading('操作记录','留存管理操作对象和原因，不存私人原文或密钥。')+`<section class="card">${auditRows(state.adminLog)}</section>`}
function adminSecurity(){return `<button class="text-button page-back" data-full="admin-back">${icon('back')} 返回上一页</button>`+adminHeading('管理账号安全','管理身份单独设置，不混入普通账号个人页面。')+`<section class="card"><div class="list-row"><span>当前管理账号</span><strong>lifexp_admin</strong></div><div class="list-row"><span>身份</span><span class="tag orange">管理员 · 示例</span></div><div class="row wrap mt"><button class="btn" data-full="admin-password">修改管理密码</button><button class="text-button" data-full="leave-admin">退出管理体验</button></div></section>`}
